<?php
require_once __DIR__.'/core.php';require_once __DIR__.'/ad_lib.php';tt_require_login();$db=tt_db_open(true);$adsReady=tt_ad_schema_ready($db);$ratingsReady=tt_schema_table_exists($db,'account_ratings');$mediaReady=tt_schema_table_exists($db,'profile_media');$q=trim((string)($_GET['q']??$_POST['q']??''));$selected=trim((string)($_GET['user']??''));$like='%'.$q.'%';
if($q!==''){$s=tt_prepare($db,'SELECT `id`,`username`,`aboutcontent`,`tags`,`created_at`,`last_login_at` FROM `accounts` WHERE `username` LIKE ? OR `aboutcontent` LIKE ? OR `tags` LIKE ? ORDER BY `username` LIMIT 100');$s->bind_param('sss',$like,$like,$like);}else{$s=tt_prepare($db,'SELECT `id`,`username`,`aboutcontent`,`tags`,`created_at`,`last_login_at` FROM `accounts` ORDER BY `username` LIMIT 100');}$s->execute();$users=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
$ratingMap=[];$myRating=[];if($ratingsReady){$r=$db->query('SELECT `target_account_id`,ROUND(AVG(`perspective`)) AS rating,COUNT(*) AS n FROM `account_ratings` GROUP BY `target_account_id`');if($r)while($x=$r->fetch_assoc())$ratingMap[(int)$x['target_account_id']]=['rating'=>(int)$x['rating'],'n'=>(int)$x['n']];$me=(int)$_SESSION['id'];$s=tt_prepare($db,'SELECT `target_account_id`,`perspective` FROM `account_ratings` WHERE `voter_account_id`=?');$s->bind_param('i',$me);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$myRating[(int)$x['target_account_id']]=(int)$x['perspective'];$s->close();}
$mediaMap=[];if($mediaReady){$r=$db->query('SELECT `account_id`,`filename`,`mime_type`,`size_bytes`,`updated_at` FROM `profile_media`');if($r)while($x=$r->fetch_assoc())$mediaMap[(int)$x['account_id']]=['kind'=>'profile_media','account_id'=>(int)$x['account_id'],'mime_type'=>$x['mime_type'],'filename'=>$x['filename']];}
// Backward-compatible avatar fallback: the newest image attached to a legacy profile post.
$r=$db->query("SELECT a.id AS account_id,p.id AS post_id,pa.mime_type,pa.filename FROM accounts a JOIN posts p ON p.name=a.username JOIN post_attachments pa ON pa.post_id=p.id WHERE p.type='profile' AND pa.mime_type LIKE 'image/%' ORDER BY p.dt DESC,p.id DESC");if($r){while($x=$r->fetch_assoc()){ $aid=(int)$x['account_id']; if(!isset($mediaMap[$aid]))$mediaMap[$aid]=['kind'=>'post_attachment','post_id'=>(int)$x['post_id'],'mime_type'=>$x['mime_type'],'filename'=>$x['filename']]; }}
$posts=[];$ads=[];$selectedOwnerId=0;if($selected!=='' && $adsReady){$x=tt_prepare($db,'SELECT `id` FROM `accounts` WHERE `username`=? LIMIT 1');$x->bind_param('s',$selected);$x->execute();$x->bind_result($selectedOwnerId);$x->fetch();$x->close();$x=tt_prepare($db,"SELECT p.`id`,p.`title`,p.`content`,p.`file`,p.`type`,pa.`mime_type` AS attachment_mime,ab.`id` AS boost_id FROM `ad_boosts` ab JOIN `posts` p ON p.`id`=ab.`post_id` LEFT JOIN `post_attachments` pa ON pa.`post_id`=p.`id` WHERE ab.`status`='active' AND ab.`budget_mills`>ab.`spent_mills` AND (ab.`target_username`=? OR ab.`target_username`='') ORDER BY (ab.`target_username`=?) DESC,ab.`budget_mills`-ab.`spent_mills` DESC LIMIT 8");$x->bind_param('ss',$selected,$selected);$x->execute();$ads=$x->get_result()->fetch_all(MYSQLI_ASSOC);$x->close();}
if($selected!==''){[$vis,$params,$types]=tt_visible_where('p');$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`tags`,p.`type`,p.`scope` FROM `posts` p WHERE '.$vis.' AND p.`name`=? ORDER BY p.`dt` DESC LIMIT 50';$params[]=$selected;$types.='s';$s=tt_prepare($db,$sql);$s->bind_param($types,...$params);$s->execute();$posts=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}$db->close();
function tt_people_signed(int $v):string{return ($v>=0?'+':'').$v;}function tt_people_media(int $id,?array $m):string{if(!$m)return '<div class="profile-avatar profile-avatar-empty" aria-label="No profile picture">'.htmlspecialchars(mb_strtoupper(mb_substr((string)$id,0,1))).'</div>';$mime=strtolower((string)($m['mime_type']??''));$src=($m['kind']??'')==='post_attachment'?'attachment.php?post='.(int)$m['post_id']:'profile_media.php?id='.$id;if(str_starts_with($mime,'image/'))return '<img class="profile-media profile-avatar" src="'.tt_h($src).'" alt="Profile picture" loading="lazy">';if(str_starts_with($mime,'video/'))return '<video class="profile-media" src="'.tt_h($src).'" controls preload="metadata"></video>';if(str_starts_with($mime,'audio/'))return '<audio class="profile-audio" src="'.tt_h($src).'" controls preload="metadata"></audio>';return '<a href="'.tt_h($src).'">Open profile media</a>';}
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · People</title></head><body><?php tt_nav('profile.php');?><main class="content"><h2>People</h2><form class="searchbar" method="get"><input name="q" value="<?=tt_h($q)?>" placeholder="Search users, descriptions, tags"><input type="submit" value="Search"></form><?php if(!$ratingsReady||!$mediaReady):?><p class="meta">Profile Moksha and profile media become available after one protected schema-maintenance run. Legacy profile-post images are used as profile pictures when available.</p><?php endif;?><section class="grid people-grid"><?php foreach($users as $u):$uid=(int)$u['id'];$rr=$ratingMap[$uid]??['rating'=>0,'n'=>0];$mine=$myRating[$uid]??0;$pm=$mediaMap[$uid]??null;$isSelected=$selected!==''&&hash_equals($selected,(string)$u['username']);?><article class="card person-card<?=$isSelected?' selected-profile':''?>"><div class="profile-heading"><?=tt_people_media($uid,$pm)?><div><h3><a href="profile.php?user=<?=urlencode($u['username'])?>"><?=tt_h($u['username'])?></a></h3><p class="moksha-summary"><strong>Moksha:</strong> <?=tt_people_signed((int)$rr['rating'])?> / 256 · <?=number_format((int)$rr['n'])?> rating<?=((int)$rr['n']===1?'':'s')?></p></div></div><p><?=nl2br(tt_h($u['aboutcontent']))?></p><p class="meta"><?=tt_h($u['tags'])?></p><?php if($ratingsReady&&$uid!==(int)$_SESSION['id']):?><form method="post" action="person_rate.php" class="rating-form profile-moksha-form"><input type="hidden" name="target_account_id" value="<?=$uid?>"><label for="person-rate-<?=$uid?>">Your Moksha rating: <output id="person-rate-out-<?=$uid?>"><?=$mine?></output></label><input class="karma-slider" id="person-rate-<?=$uid?>" type="range" name="perspective" min="-256" max="256" step="1" value="<?=$mine?>" oninput="document.getElementById('person-rate-out-<?=$uid?>').value=this.value"><div class="slider-labels"><span>−256</span><span>0</span><span>+256</span></div><button type="submit"><?=$mine!==0?'Update Moksha rating':'Set Moksha rating'?></button></form><?php endif;?><?php if($u['username']!==($_SESSION['name']??'')):?><p><a href="friend.php?user=<?=urlencode($u['username'])?>">Friend controls</a></p><?php else:?><p><a href="account.php">Edit profile & media</a></p><?php endif;?></article><?php endforeach;?></section>
<?php if($selected!=='' && $ads):?><h2>Sponsored / boosted on <?=tt_h($selected)?>'s page</h2><section class="grid ad-grid"><?php foreach($ads as $a):?><article class="card ad-card tt-expand-card" data-tt-expandable="1" aria-expanded="false" data-boost-id="<?=(int)$a['boost_id']?>" data-page-owner-id="<?=(int)$selectedOwnerId?>"><p class="meta">Sponsored · natural credit exchange enabled</p><h3><a href="post.php#post-<?=(int)$a['id']?>"><?=tt_h($a['title'])?></a></h3><p><?=nl2br(tt_h($a['content']))?></p><?=tt_ad_attachment_html($a)?></article><?php endforeach;?></section><?php endif;?><?php if($selected!==''):?><h2>Posts by <?=tt_h($selected)?></h2><section class="grid"><?php foreach($posts as $p):?><article class="card post-card" data-post-expandable="1" aria-expanded="false"><h3><?=tt_h($p['title'])?></h3><p class="meta"><?=tt_h($p['dt'])?> · <?=tt_h($p['type'])?> · <?=tt_h(trim($p['scope']))?></p><p><?=nl2br(tt_h($p['content']))?></p></article><?php endforeach;?><?php if(!$posts):?><article class="card">No visible posts.</article><?php endif;?></section><?php endif;?></main><script>document.querySelectorAll('[data-boost-id]').forEach(el=>{const f=new FormData();f.set('boost_id',el.dataset.boostId);f.set('page_owner_id',el.dataset.pageOwnerId||'0');fetch('ad_impression.php',{method:'POST',body:f,credentials:'same-origin',keepalive:true}).catch(()=>{});});</script></body></html>